# Ansys script methods
def ChangePropertyName(name, name_New):
  oEditor.ChangeProperty(["NAME:AllTabs",
    ["NAME:Geometry3DAttributeTab",
    ["NAME:PropServers", str(name)],
    ["NAME:ChangedProps",
    ["NAME:Name", "Value:=", str(name_New)]]]])

def SubtractObjects(blankPartList, toolPartList, keepOriginals):
  # Subtract tool parts boundaries from blank part boundaries
  oEditor.Subtract(["NAME:Selections",
    "Blank Parts:=", str(blankPartList),
    "Tool Parts:=", str(toolPartList)],
    ["NAME:SubtractParameters", "KeepOriginals:=", keepOriginals])

def CreateOutputVariable(variableName, Expression):
  oOutputVarModule.CreateOutputVariable(str(variableName),
    str(Expression),
    "Setup1 : Transient", "Transient", [])

def BandToolSubtraction(bandTool):
  numObjects = oEditor.GetNumObjects()
  objectString = ""
  for objectLoop in range(numObjects - 1):
    name = oEditor.GetObjectName(int(objectLoop))
    if bandTool != str(name):
      objectString = objectString + str(name) + ","

  oEditor.Subtract(["NAME:Selections",
    "Blank Parts:=", str(objectString),
    "Tool Parts:=", str(bandTool)],
    ["NAME:SubtractParameters", "KeepOriginals:=",  False])

def RotateObject(name, skewAngle):
  oEditor.Rotate(["NAME:Selections",
	  "Selections:=", str(name),
    "NewPartsModelFlag:=", "Model"],
	  ["NAME:RotateParameters",
     "RotateAxis:=", "Z",
     "RotateAngle:=", str(skewAngle).replace(",", ".") + "deg"])

def SplitObject(name, side):
  oEditor.Split(["NAME:Selections",
    "Selections:=", str(name),
    "NewPartsModelFlag:=", "Model"],
    ["Name:SplitToParameters",
     "SplitPlane:=", "ZX",
     "WhichSide:=", str(side),
     "ToolType:=", "PlaneTool",
     "ToolEntityID:=", -1,
     "SplitCrossingObjectsOnly:=", False,
     "DeleteInvalidObjects:=", True])

def CreateRectangleObject(name, Xstart, Ystart, Zstart, Width, Height, Axis):
  oEditor.CreateRectangle(["NAME:RectangleParameters",
    "IsCovered:=", True,
    "XStart:=", str(Xstart),
    "YStart:=", str(Ystart),
    "ZStart:=", str(Zstart),
    "Width:=", str(Width),
    "Height:=", str(Height),
    "WhichAxis:=", str(Axis)],
    ["NAME:Attributes",
     "Name:=", str(name),
     "Flags:=", "",
     "Color:=", "(143 175 143)",
     "Transparency:=", 0,
     "PartCoordinateSystem:=", "Global",
     "UDMId:=", "",
     "MaterialValue:=", "\"\"",
     "SurfaceMaterialValue:=", "\"\"",
     "SolveInside:=", True,
     "ShellElement:=", False,
     "ShellElementThicknesS:=", "0mm",
     "ReferenceTemperature:=", "20cel",
     "IsMaterialEditable:=", True,
     "UseMaterialAppearance:=", False,
     "IsLightweight:=", False])

def extrudeMoveObject(Name, TranslateVectorZ, SweepVectorZ):
  oEditor.Move(["NAME:Selections",
    "Selections:=", str(Name),
    "NewPartsModelFlag:=", "Model"],
    ["NAME:TranslateParameters",
     "TranslateVectorX:=", "0mm",
     "TranslateVectorY:=", "0mm",
     "TranslateVectorZ:=", str(TranslateVectorZ).replace(",", ".")])

  oEditor.SweepAlongVector(["NAME:Selections",
    "Selections:=", str(Name),
    "NewPartsModelFlag:=", "Model"],
    ["NAME:VectorSweepParameters",
     "DraftAngle:=", "0deg",
     "DraftType:=", "Round",
     "CheckFaceFaceIntersection:=", False,
     "SweepVectorX:=",  "0mm",
     "SweepVectorY:=", "0mm",
     "SweepVectorZ:=", str(SweepVectorZ).replace(",", ".")])

def duplicateObject(nameCopy, nameNew, ZPosition):
  DuplicatedName =	oEditor.DuplicateAlongLine(["NAME:Selections",
    "Selections:=", str(nameCopy),
    "NewPartsModelFlag:=", "Model"],
	  ["NAME:DuplicateToAlongLineParameters",
	   "CreateNewObjects:=", True,
	   "XComponent:=", "0mm",
	   "YComponent:=", "0mm",
	     "ZComponent:=", "-" + str(ZPosition).replace(",", ".") + "mm",
	   "NumClones:=", "2"],
	  ["NAME:Options", "DuplicateAssignments:=", False],
	  ["CreateGroupsForNewObjects:=", False])
  ChangePropertyName(DuplicatedName[0], nameNew)

def moveObject(name, TranslateVectorZ):
  oEditor.Move(["NAME:Selections",
    "Selections:=", str(name),
    "NewPartsModelFlag:=", "Model"],
    ["NAME:TranslateParameters",
     "TranslateVectorX:=", "0mm",
     "TranslateVectorY:=", "0mm",
     "TranslateVectorZ:=", str(TranslateVectorZ).replace(",", ".") + "mm"])

def extrudeSkewObject(name, sweep, skewAngle):
  oEditor.SweepAlongVector(["NAME:Selections",
    "Selections:=", str(name),
    "NewPartsModelFlag:=", "Model"],
    ["NAME:VectorSweepParameters",
     "DraftAngle:=", "0deg",
     "DraftType:=", "Round",
     "CheckFaceFaceIntersection:=", False,
     "SweepVectorX:=",  "0mm",
     "SweepVectorY:=", "0mm",
     "SweepVectorZ:=", "-" + str(sweep).replace(",", ".") + "mm"])

  if float(skewAngle) != 0:
    RotateObject(name, skewAngle)

def applyInsulationToFace(magnetName, zCoord):
  # Apply insulation to bottom face of magnetName
  oFaceIDs = oEditor.GetFaceIDs(str(magnetName))
  for faceID in oFaceIDs:
    oApplyInsulation = True
    oVertexIDs = oEditor.GetVertexIDsFromFace(int(faceID))

    for vertexID in oVertexIDs:
      vertex = oEditor.GetVertexPosition(vertexID)

      if round(float(vertex[2]), 4) != round(float(zCoord), 4):
        oApplyInsulation = False
        break

    if oApplyInsulation == True:
      oBoundaryModule.AssignInsulating(["NAME:Insulation_" + str(magnetName),"Faces:=", [int(faceID)]])

def CreateWindingTerminal(coilName, terminalName, terminalType):
  oEditor.Copy(["NAME:Selections", "Selections:=", str(coilName)])
  pasteNames = oEditor.Paste()
  ChangePropertyName(pasteNames[0], terminalName)

  oEditor.ChangeProperty(["NAME:AllTabs",
    ["NAME:Geometry3DCmdTab",
    ["NAME:PropServers",
     str(terminalName) + ":CreateUserDefinedPart:1"],
    ["NAME:ChangedProps",
     ["NAME:Coordinate System",
      "Value:=",  "PhTerminal_CS"],
      ["NAME:InfoCoil",
       "Value:=", str(terminalType)]]]]
)

def GetModelLength_Axial():
  boundaries = oEditor.GetModelBoundingBox()
  return (float(boundaries[5]) - float(boundaries[2])) * 1.05

def GetModelAxial_Center():
  boundaries = oEditor.GetModelBoundingBox()
  return abs(float(boundaries[5])) - abs(float(boundaries[2]))

def CreateMagnetCoordinateSystem(magnetName, origin_X, origin_Y, origin_Z, vector_XX, vector_XY, vector_YX, vector_YY, ModelType):
  oEditor.SetWCS(["NAME:SetWCS Parameter", "Working Coordinate System:=", "Global"])
  oEditor.CreateRelativeCS(["NAME:RelativeCSParameters",
    "Mode:=", "Axis/Position",
    "OriginX:=", str(origin_X).replace(",", ".") + "mm",
    "OriginY:=", str(origin_Y).replace(",", ".") + "mm",
    "OriginZ:=", str(origin_Z).replace(",", ".") + "mm",
    "XAxisXvec:=", str(vector_XX).replace(",", ".") + "mm",
    "XAxisYvec:=", str(vector_XY).replace(",", ".") + "mm",
    "XAxisZvec:=", "0mm",
    "YAxisXvec:=", str(vector_YX).replace(",", ".") + "mm",
    "YAxisYvec:=", str(vector_YY).replace(",", ".") + "mm",
    "YAxisZvec:=", "0mm"],
    ["NAME:Attributes", "Name:=", "CS_" + str(magnetName)])

  oEditor.ChangeProperty(["NAME:AllTabs",
    ["NAME:Geometry3DAttributeTab",
     ["NAME:PropServers", str(magnetName)],
     ["NAME:ChangedProps",
      ["NAME:Orientation", "Value:=", "CS_" + str(magnetName)]]]])

  if ModelType == 0:
    # Assign excitation to magnets for magnet eddy current loss calculations
    oBoundaryModule.AssignCurrent(["NAME:" + str(magnetName),
      "Objects:=", [str(magnetName)],
      "Current:=", "0A" ,
      "IsPositive:=", True])

